import json,subprocess
unit='nvidia-cdi-refresh.service'
def run(args,check=True):return subprocess.run(args,text=True,capture_output=True,check=check)
before=run(['systemctl','is-enabled',unit],False).stdout.strip()
if before!='enabled':run(['systemctl','enable',unit])
devices=run(['nvidia-ctk','cdi','list']).stdout.split()
if 'nvidia.com/gpu=all' not in devices:run(['systemctl','start',unit]);devices=run(['nvidia-ctk','cdi','list']).stdout.split()
assert 'nvidia.com/gpu=all' in devices
print(json.dumps({'before_enabled':before,'enabled':run(['systemctl','is-enabled',unit]).stdout.strip(),'devices':devices,'toolkit':run(['nvidia-ctk','--version']).stdout}))
